from pwn import *
import socket

def check_port(port):
    try:
        conn = remote('0.0.0.0', port, timeout=1)
        print(f"[+] Port {port} is open!")
        try:
            initial_data = conn.recvuntil(b'\n', timeout=2)
            print(f"Received: {initial_data}")
        except:
            pass
        conn.close()
    except:
        pass

# Common CTF ports
ports = [1337, 4444, 9990, 9991, 9992, 9999]
for port in ports:
    check_port(port)

